import{_ as p,a0 as l,w as o,s as d,ao as r,I as i,x as a,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const q=JSON.parse('{"title":"PyLint 的优点、缺点和危险 | LCTT x X-CMD","titleTemplate":false,"description":"PyLint 的优点、缺点和危险 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"PyLint 的优点、缺点和危险 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"PyLint 的优点、缺点和危险 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20220919 PyLint- The good, the bad, and the ugly","title":"PyLint 的优点、缺点和危险","tag":"202210","desc":""},"relativePath":"202210/20220919 PyLint- The good, the bad, and the ugly.md","filePath":"[post].md"}'),h={name:"202210/20220919 PyLint- The good, the bad, and the ugly.md"};function c(u,s,g,k,b,f){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="pylint-的优点、缺点和危险" tabindex="-1">PyLint 的优点、缺点和危险 <a class="header-anchor" href="#pylint-的优点、缺点和危险" aria-label="Permalink to “PyLint 的优点、缺点和危险”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202210/16/093840z9pnzfv9ykfccoq9.jpg" alt=""></p><blockquote><p>充分利用 PyLint。</p></blockquote><p>敲黑板：PyLint 实际上很好！</p><p>“PyLint 可以拯救你的生命”，这是一句夸张的描述，但没有你想象的那么夸张。PyLint 可以让你远离非常难找到的和复杂的缺陷。最差的情况下，它只可以节省测试运行的时间。最好的情况下，它可以帮你避免生产环境中复杂的错误。</p><h3 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to “优点”">​</a></h3><p>我不好意思说这种情况是多么普遍。测试的命名总是<em>那么奇怪</em>：没有人关心这个名称，而且通常也找不到一个自然的名称。例如以下代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def test_add_small():</span></span>
<span class="line"><span>    # Math, am I right?</span></span>
<span class="line"><span>    assert 1 + 1 == 3</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>def test_add_large():</span></span>
<span class="line"><span>    assert 5 + 6 == 11</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>def test_add_small():</span></span>
<span class="line"><span>    assert 1 + 10 == 11</span></span></code></pre></div><p>测试生效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>collected 2 items                                                                         </span></span>
<span class="line"><span>test.py .. </span></span>
<span class="line"><span>2 passed</span></span></code></pre></div><p>但问题是：如果你覆盖了一个测试的名称，测试框架将愉快地跳过这个测试！</p><p>实际上，这些文件可能有数百行，而添加新测试的人可能并不知道所有的名称。除非有人仔细查看测试输出，否则一切看起来都很好。</p><p>最糟糕的是，<em>被覆盖测试的添加</em>、<em>被覆盖测试造成的破坏</em>，以及<em>连锁反应的问题</em>可能要几天、几月甚至几年才能发现。</p><h3 id="pylint-会找到它" tabindex="-1">PyLint 会找到它 <a class="header-anchor" href="#pylint-会找到它" aria-label="Permalink to “PyLint 会找到它”">​</a></h3><p>就像一个好朋友一样，PyLint 可以帮助你。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>test.py:8:0: E0102: function already defined line 1</span></span>
<span class="line"><span>     (function-redefined)</span></span></code></pre></div><h3 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to “缺点”">​</a></h3><p>就像 90 年代的情景喜剧一样，你对 PyLint 了解的越多，问题就越多。以下是一个库存建模程序的常规代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&quot;&quot;&quot;Inventory abstractions&quot;&quot;&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import attrs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@attrs.define</span></span>
<span class="line"><span>class Laptop:</span></span>
<span class="line"><span>    &quot;&quot;&quot;A laptop&quot;&quot;&quot;</span></span>
<span class="line"><span>    ident: str</span></span>
<span class="line"><span>    cpu: str</span></span></code></pre></div><p>但 PyLint 似乎有自己的观点（可能形成于 90 年代），并且不怕把它们作为事实陈述出来：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pylint laptop.py | sed -n &#39;/^laptop/s/[^ ]*: //p&#39;</span></span>
<span class="line"><span>R0903: Too few public methods (0/2) (too-few-public-methods)</span></span></code></pre></div><h3 id="危险" tabindex="-1">危险 <a class="header-anchor" href="#危险" aria-label="Permalink to “危险”">​</a></h3><p>有没有想过在一个数百万人使用的工具中加入自己未证实的观点？PyLint 每月有 1200 万次下载。</p><blockquote><p>“如果太挑剔，人们会取消检查” — 这是 PyLint GitHub 的 6987 号议题，于 2022 年 7 月 3 号提出</p></blockquote><p>对于添加一个可能有许多误报的测试，它的态度是 ... “<em>嗯</em>”。</p><h3 id="让它为你工作" tabindex="-1">让它为你工作 <a class="header-anchor" href="#让它为你工作" aria-label="Permalink to “让它为你工作”">​</a></h3><p>PyLint 很好，但你需要小心地与它配合。为了让 PyLint 为你工作，以下是我推荐的三件事：</p><h4 id="_1、固定版本" tabindex="-1">1、固定版本 <a class="header-anchor" href="#_1、固定版本" aria-label="Permalink to “1、固定版本”">​</a></h4><p>固定你使用的 PyLint 版本，避免任何惊喜！</p><p>在你的 <code>.toml</code> 文件中定义:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[project.optional-dependencies]</span></span>
<span class="line"><span>pylint = [&quot;pylint&quot;]</span></span></code></pre></div><p>在代码中定义：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from unittest import mock</span></span></code></pre></div><p>这与以下代码对应：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># noxfile.py</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>@nox.session(python=VERSIONS[-1])</span></span>
<span class="line"><span>def refresh_deps(session):</span></span>
<span class="line"><span>    &quot;&quot;&quot;Refresh the requirements-*.txt files&quot;&quot;&quot;</span></span>
<span class="line"><span>    session.install(&quot;pip-tools&quot;)</span></span>
<span class="line"><span>    for deps in [..., &quot;pylint&quot;]:</span></span>
<span class="line"><span>        session.run(</span></span>
<span class="line"><span>            &quot;pip-compile&quot;,</span></span>
<span class="line"><span>            &quot;--extra&quot;,</span></span>
<span class="line"><span>            deps,</span></span>
<span class="line"><span>            &quot;pyproject.toml&quot;,</span></span>
<span class="line"><span>            &quot;--output-file&quot;,</span></span>
<span class="line"><span>            f&quot;requirements-{deps}.txt&quot;,</span></span>
<span class="line"><span>        )</span></span></code></pre></div><h4 id="_2、默认禁止" tabindex="-1">2、默认禁止 <a class="header-anchor" href="#_2、默认禁止" aria-label="Permalink to “2、默认禁止”">​</a></h4><p>禁用所有检查，然后启用那些你认为误报比率高的。（不仅仅是漏报/误报的比率！）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># noxfile.py</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>@nox.session(python=&quot;3.10&quot;)</span></span>
<span class="line"><span>def lint(session):</span></span>
<span class="line"><span>    files = [&quot;src/&quot;, &quot;noxfile.py&quot;]</span></span>
<span class="line"><span>    session.install(&quot;-r&quot;, &quot;requirements-pylint.txt&quot;)</span></span>
<span class="line"><span>    session.install(&quot;-e&quot;, &quot;.&quot;)</span></span>
<span class="line"><span>    session.run(</span></span>
<span class="line"><span>        &quot;pylint&quot;,</span></span>
<span class="line"><span>        &quot;--disable=all&quot;,</span></span>
<span class="line"><span>        *(f&quot;--enable={checker}&quot; for checker in checkers)</span></span>
<span class="line"><span>        &quot;src&quot;,</span></span>
<span class="line"><span>    )</span></span></code></pre></div><h4 id="_3、检查器" tabindex="-1">3、检查器 <a class="header-anchor" href="#_3、检查器" aria-label="Permalink to “3、检查器”">​</a></h4><p>以下是我喜欢的检查器。加强项目的一致性，避免一些明显的错误。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>checkers = [</span></span>
<span class="line"><span>    &quot;missing-class-docstring&quot;,</span></span>
<span class="line"><span>    &quot;missing-function-docstring&quot;,</span></span>
<span class="line"><span>    &quot;missing-module-docstring&quot;,</span></span>
<span class="line"><span>    &quot;function-redefined&quot;,</span></span>
<span class="line"><span>]</span></span></code></pre></div><h3 id="使用-pylint" tabindex="-1">使用 PyLint <a class="header-anchor" href="#使用-pylint" aria-label="Permalink to “使用 PyLint”">​</a></h3><p>你可以只使用 PyLint 好的部分。在 CI 中运行它以保持一致性，并使用常用检查器。</p><p>放弃不好的部分：默认禁止检查器。</p><p>避免危险的部分：固定版本以避免意外。</p><hr>`,46)),i("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/22/9/pylint-good-bad-ugly"},{default:t(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/22/9/pylint-good-bad-ugly",-1)])]),_:1})]),i("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/moshez"},{default:t(()=>[...s[2]||(s[2]=[a("Moshe Zadka",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lkxed"},{default:t(()=>[...s[3]||(s[3]=[a("lkxed",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/MjSeven"},{default:t(()=>[...s[4]||(s[4]=[a("MjSeven",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const x=p(h,[["render",c]]);export{q as __pageData,x as default};
